-- pipeline/upsert-outlet
-- Adds or updates one outlet from content/outlets.json (`pnpm pipeline:outlets`). Health columns are kept.
--
-- Parameters, with the example values used to render this file:
--   $1 = "example-news"
--   $2 = "Example News"
--   $3 = "en"
--   $4 = "https://example.com/feed"
--   $5 = true
--   $6 = "Example News"
--   $7 = "en"
--   $8 = "https://example.com/feed"
--   $9 = true
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

insert into "outlets" ("id", "slug", "name", "language", "feed_url", "enabled", "last_ok_at", "last_error", "consecutive_failures", "created_at", "updated_at")
values (default, $1, $2, $3, $4, $5, default, default, default, default, default)
on conflict ("slug")
do update
set "name" = $6, "language" = $7, "feed_url" = $8, "enabled" = $9, "updated_at" = now()
returning "id";
